package common

import "strconv"

// UniqueID identifies an Equipment, GrenadeProjectile or Inferno.
// It is generated by this library and needed because demo-files reuse entity ids.
//
// The id is unique within the Parser that created it and reproducible across parses of the same demo
// (with the same library version and ParserConfig). Ids from different Parser instances may collide,
// so don't key data across demos by it.
//
// Ids are assigned in creation order, starting at 1.
type UniqueID uint64

// String returns the id as a decimal number.
func (id UniqueID) String() string {
	return strconv.FormatUint(uint64(id), 10)
}

// Uint64 returns the id as a uint64.
func (id UniqueID) Uint64() uint64 {
	return uint64(id)
}
